export const baseUserContract = {
  requires: [auth('user')],
  ensures: [auditLog('user_operation')]
};

export const adminUserContract = {
  requires: [auth('admin'), rateLimit('admin_operation', 20)],
  ensures: [auditLog('admin_operation')]
};

